def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]
    opp_d = sum(1 for x in opp if x == 'D')
    r5_d = sum(1 for x in opp[-5:] if x == 'D')
    r10_d = sum(1 for x in opp[-10:] if x == 'D')
    r5_my = sum(1 for x in my[-5:] if x == 'D')
    last_my, last_opp = history[-1]

    if n >= 2:
        prev_my, prev_opp = history[-2]
    else:
        prev_my, prev_opp = '', ''

    if opp_d == 0:
        if n < 9:
            return 'C'
        if n == 9:
            return 'D'
        if n == 10:
            return 'C'
        if n >= 97:
            return 'D'
        if my[-2] == 'D' and my[-1] == 'D':
            return 'C'
        return 'D'

    if opp_d == n:
        return 'D'
    if opp_d * 5 >= 3 * n:
        return 'D'
    if r10_d >= 8:
        return 'D'
    if r5_d >= 4 and opp_d * 2 >= n:
        return 'D'

    if last_opp == 'C':
        if (last_my == 'D' and opp_d <= 2 and r5_d == 0 and
                n >= 11 and n <= 96):
            if n >= 2 and my[-2] == 'D' and my[-1] == 'D':
                return 'C'
            return 'D'
        return 'C'

    if n >= 2 and prev_my == 'D' and prev_opp == 'C':
        if opp_d <= max(3, n // 4) and r5_d <= 2:
            return 'C'
        return 'D'

    if last_my == 'C':
        return 'D'

    if (n >= 2 and prev_opp == 'C' and
            opp_d <= max(3, n // 4) and
            r5_d <= 2 and r5_my <= 2):
        return 'C'

    return 'D'
